import{z as A,x as p,o,c as i,q as E,j as t,D as a,d as r,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Qwen3.5-OCR：原生 PDF 与多轮抽取","description":"","frontmatter":{"title":"Qwen3.5-OCR：原生 PDF 与多轮抽取","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen35-ocr.md","filePath":"llm/qwen35-ocr.md","lastUpdated":1791413859000}'),d={name:"llm/qwen35-ocr.md"};function c(B,e,D,P,m,_){const n=p("Mermaid");return o(),i("div",null,[e[2]||(e[2]=E('<h1 id="qwen3-5-ocr-原生-pdf-与多轮抽取" tabindex="-1">Qwen3.5-OCR：原生 PDF 与多轮抽取 <a class="header-anchor" href="#qwen3-5-ocr-原生-pdf-与多轮抽取" aria-label="Permalink to &quot;Qwen3.5-OCR：原生 PDF 与多轮抽取&quot;">​</a></h1><div class="epigraph"><p>qwen3.5-ocr 支持通过 Response API 直接传入 PDF 文件进行文档解析，无需手动将 PDF 拆分为图片。</p><footer>—— Qwen Cloud / 阿里云百炼文字提取文档</footer></div><p>前代文档 OCR 的默认路径是：把 PDF 每一页光栅化成图，再按多图输入逐页识别。光栅化丢掉字体、矢量路径、嵌入文本层和页面树，只留下像素。调用方还要自己管分页、分辨率和跨页上下文。Qwen3.5-OCR 基于 Qwen3.5 架构，把文档解析、文字定位和关键信息抽取做了专用强化，并明确两件新产品能力：原生 PDF（不必先渲染成图）与多轮对话式抽取。前者改的是输入表示，后者改的是交互状态。本篇只谈这两件事如何改变文档 AI 的接口形状，不把全部卡证类型列表抄进正文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PDF 不是图像容器。一页里可以同时有：可选择的文本对象、矢量线框、嵌入字体、扫描图像 XObject、以及标注和表单域。若一律 <code>pdf2image</code>，文本层被毁掉，模型必须从像素里把已经数字存在的字符再认一遍，既慢又引入识别误差。扫描件 PDF 则相反：没有文本层，光栅化不可避免。一刀切的「先转图」把两类文档绑上同一条最差路径。</p><p><span class="marginnote">术语翻译：「光栅化」就是给 PDF 拍照——把每一页变成固定分辨率的像素图。拍照之后，可复制的文字、清晰的字体轮廓这些「活信息」全变成死像素，模型只能重新认字；而数字版 PDF 里这些字符本来就以文本形式躺在文件里。</span></p><p>单轮 OCR 的条件是 \\(p(y_1\\mid D)\\)，\\(D\\) 为整份文件。多轮变成</p> \\[p(y_{t}\\mid D, y_{\\lt t}, q_{\\le t}), \\]<p>查询 \\(q_t\\) 在对话中才会收窄抽取目标。用户先要全文，再问「金额是多少」，再改 schema 要「只要税前」。每次把同一份文件当新请求，视觉 token 重复计费，且模型看不到上一轮已经对齐过的字段。早期 Qwen-VL-OCR 快照按单条消息处理，不保留上下文。文档业务却天然是多轮的：核对、追问、纠正、补字段。</p><h3 id="渲染损失与跨页状态" tabindex="-1">渲染损失与跨页状态 <a class="header-anchor" href="#渲染损失与跨页状态" aria-label="Permalink to &quot;渲染损失与跨页状态&quot;">​</a></h3><p>光栅化还引入分辨率契约。DPI 太低，小号字不可读；太高，页数一多就打满 <code>max_pixels</code> 与上下文。原生 PDF 路径若能直接消费页面描述，理论上可按对象而不是按像素预算工作——至少对数字文档如此。跨页表格、脚注续页、目录与正文分离，则要求模型在记忆里保持「上一页最后一行」和「表头」，这不是单张图 VQA 的设定。多轮与长 PDF 是同一类状态问题的两个尺度：轮次之间的状态，和页与页之间的状态。</p><p><span class="marginnote">原生 PDF 不是万能输入。加密文件、损坏交叉引用表、极端巨大的单页矢量、以及以图片为主的扫描件，仍会退回光栅或直接失败。产品文档给出页数与体积上限（如最大 50 页、不超过 100MB），这是服务约束，不是模型隐层宽度定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Qwen3.5-OCR 允许在 Response API 中直接传 PDF 做文档解析；该路径不支持把同一文件随便塞进普通 Chat Completions。调用方可设置 <code>ocr_options.task</code>，例如 <code>document_parsing</code>，让输出走 LaTeX 或其他任务契约。数字页不必先变成 JPEG。扫描页在服务端仍可能被内部光栅化，但对调用方来说契约已经是「文件进、结构出」，而不是「自己管 dpi」。</p><p>多轮方面，从 <code>qwen3.5-ocr</code> 起支持对话：后续轮可以不带图，只发纯文本追问，依赖已上传文档的上下文。内置任务与用户自定义 Prompt 结合，不再强制覆盖；任务结构化结果通过 <code>ocr_result</code> 返回。这把「模板抽取」和「自然语言核对」叠在同一会话里。例如先按 schema 抽发票字段，再问某一行是否含税，不必重新传文件。</p>',15)),(o(),t(l,null,{default:a(()=>[s(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20PDF%5B%22%E5%8E%9F%E7%94%9F%20PDF%22%5D%20--%3E%20API%5B%22Response%20API%22%5D%0A%20%20API%20--%3E%20PARSE%5B%22%E6%96%87%E6%A1%A3%E8%A7%A3%E6%9E%90%20%2F%20KIE%22%5D%0A%20%20PARSE%20--%3E%20R%5B%22ocr_result%22%5D%0A%20%20R%20--%3E%20Q%5B%22%E5%A4%9A%E8%BD%AE%E7%BA%AF%E6%96%87%E6%9C%AC%E8%BF%BD%E9%97%AE%22%5D%0A%20%20Q%20--%3E%20A%5B%22%E5%9F%BA%E4%BA%8E%E5%B7%B2%E8%A7%A3%E6%9E%90%E7%8A%B6%E6%80%81%E4%BD%9C%E7%AD%94%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<h3 id="与「多图假长文档」的差别" tabindex="-1">与「多图假长文档」的差别 <a class="header-anchor" href="#与「多图假长文档」的差别" aria-label="Permalink to &quot;与「多图假长文档」的差别&quot;">​</a></h3><p>把 PDF 预渲染成 \\(N\\) 张图再当多图 VQA，页间关系完全靠提示词「这是第 i 页」。模型看到的是 \\(N\\) 组互不共享 PDF 对象树的视觉 token。原生路径至少保留文件级身份：同一文档、页序、可能的文本层。多轮则在时间维上复用这份身份。两者一起，才接近「打开一份文件然后对话」，而不是「每次邮寄一包截图」。</p><p>像素预算仍然存在。图像输入仍有 <code>min_pixels</code> / <code>max_pixels</code>；PDF 有页数和体积上限。原生并不等于无限页。超过上限要在应用层切分，切分时必须自己处理跨文件边界的表和段落——模型不会自动合并两次请求里的半张表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多轮抽取改变的是条件前缀。第一轮条件是文件表示（页面编码或内部光栅加文本层），输出是转写或 JSON。后续轮把已经生成的结构放进对话历史，新的查询是短文本。视觉编码器不必每轮重跑——这是服务端缓存与计费细节，但对机制的意义是：追问是语言对结构的查询，不是重新感知。若历史被截断，追问就退回无记忆的单轮，可能与文件不一致。</p>',5)),(o(),t(l,null,{default:a(()=>[s(n,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20LR%0A%20%20D%5B%22%E6%96%87%E6%A1%A3%20D%20%E4%B8%8A%E4%BC%A0%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20R1%5B%22%E7%AC%AC%E4%B8%80%E8%BD%AE%EF%BC%9A%E8%A7%A3%E6%9E%90%E5%87%BA%E7%BB%93%E6%9E%84%20y1%22%5D%0A%20%20R1%20--%3E%20H%5B%22%E4%BC%9A%E8%AF%9D%E5%8E%86%E5%8F%B2%E4%BF%9D%E7%95%99%20y1%22%5D%0A%20%20H%20--%3E%20Q2%5B%22%E7%AC%AC%E4%BA%8C%E8%BD%AE%E8%BF%BD%E9%97%AE%20q2%EF%BC%88%E7%BA%AF%E6%96%87%E6%9C%AC%EF%BC%89%22%5D%0A%20%20Q2%20--%3E%20R2%5B%22%E5%9F%BA%E4%BA%8E%20y1%20%E4%BD%9C%E7%AD%94%EF%BC%8C%E4%B8%8D%E9%87%8D%E6%96%B0%E7%9C%8B%E5%9B%BE%22%5D%0A%20%20H%20-.%E8%8B%A5%20y1%20%E6%9C%89%E9%94%99.-%3E%20ERR%5B%22%E9%94%99%E8%AF%AF%E8%A2%AB%E5%BD%93%E6%88%90%E4%BA%8B%E5%AE%9E%E7%BB%A7%E7%BB%AD%E7%94%A8%22%5D%0A%20%20ERR%20--%3E%20FIX%5B%22%E9%A1%BB%E5%9C%A8%E9%A6%96%E8%BD%AE%E6%A0%A1%E9%AA%8C%E6%88%96%E7%BA%A0%E9%94%99%E8%BD%AE%E4%BF%AE%E6%AD%A3%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<p><span class="marginnote">为什么重要：多轮会把第一轮的错字「转正」。首轮把金额 1,000 认成 1,900，之后再问「金额是多少」，模型都会自信地答 1,900——追问不是重新核对，而是在错误答案上继续推理。所以关键字段要么首轮落库校验，要么立刻用纠错轮指出，不能指望多问几轮自动变对。</span></p><p>原生 PDF 改变的是感知前端。文本对象可以按阅读顺序注入为离散 token，矢量与图像仍走视觉。混合页（上半扫描、下半数字字）需要两种前端对齐到同一阅读坐标。这比「整页都是图」难，也比「整页都是文本层」难。模型若过度信任文本层，会忽略盖章和手写；若忽略文本层，又浪费已有字符。工程上通常文本层当强先验、图像当校验，但公开文档并未把内部融合写成可调超参，调用方只能通过任务类型和追问来间接触发不同行为。</p><p><span class="marginnote">Response API 与 Chat API 的能力不对称：PDF 解析被绑在 Response 上。集成时不要假设「换一个 OpenAI 兼容 base URL 就能传 <code>file</code>」。协议选择和模型选择同样决定能否原生吃 PDF。</span></p><h3 id="卡证与对话的交互" tabindex="-1">卡证与对话的交互 <a class="header-anchor" href="#卡证与对话的交互" aria-label="Permalink to &quot;卡证与对话的交互&quot;">​</a></h3><p>文档称 Qwen3.5-OCR 在身份证、驾驶证等业务卡证上的信息抽取明显增强，并支持数十种证照票据类型。多轮在这里的典型用法不是闲聊，而是纠错：第一轮 JSON 某字段为 <code>null</code> 或 <code>?</code>，用户补充拍摄角度或改 schema 再抽。因为任务通道与 Prompt 并存，纠错指令不会把 KIE 头整个关掉。幻觉风险仍在：文字过密或过糊时，模型可能编造笔画；与文字提取无关的开放问题，文档明确不保证准确。多轮会放大这种风险——一旦第一轮写进错误字段，后续追问可能把错误当成已验证事实。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>页数、体积、超时和计费按页或按 token，都会比单图 OCR 更陡。50 页上限意味着长报告要切片；切片策略错误会造成目录页与正文页在不同会话里，多轮记忆对不上。扫描件占满体积预算时，原生 PDF 的好处只剩少一次客户端转码，服务端仍在认像素。</p><p><span class="marginnote">数字实例：100 MB 总量 ÷ 50 页 = 平均每页只摊 2 MB。一张 300 dpi 的 A4 彩色扫描 JPEG 通常就要 1–3 MB——也就是说整本扫描件三四页就可能顶到体积预算；数字版 PDF 一页往往只有几十 KB，差距正来自「像素 vs 文本」。</span></p><p>多轮会话默认不在服务端永久保存。调用方需自行传历史，或使用 Response 的上一轮标识一类机制。过长的 <code>ocr_result</code> 塞进历史会挤掉页面证据。应把结构化结果落库，对话里只留摘要和文档句柄，而不是把整本 LaTeX 当聊天记录。</p><p><span class="marginnote">不要把原生 PDF 理解成「模型执行了 JavaScript 或打开了附件」。OCR 路径消费的是页面外观与文本抽取，不是完整 PDF 运行时。表单提交、数字签名校验、嵌入文件解包属于另一类文档工作流。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen3.5-OCR 的关键接口变化是原生 PDF 输入与多轮对话式抽取，不必先把每一页渲染成图再当互无关系的多图 VQA。</li><li>PDF 走 Response API，并受页数与体积上限约束；扫描件内部仍可能光栅化。</li><li>多轮允许不带图追问，内置任务结果与用户 Prompt 并存，结构化输出在 <code>ocr_result</code>。</li><li>追问是对已解析状态的语言查询；历史截断或第一轮幻觉会被后续轮当成事实。</li><li>与文字无关的开放问答不在 OCR 契约内；过密过糊仍会幻觉。</li><li>出处：Qwen Cloud / 阿里云百炼《文字提取》中 Qwen3.5-OCR 能力说明、PDF 文档解析与多轮对话限制。该产品线无公开同名 arXiv 技术报告，不以虚构编号代替文档。</li></ul>',12))])}const h=A(d,[["render",c]]);export{F as __pageData,h as default};
